export function htmlToMarkdown(html: string): string {
  return decodeHtml(
    html
      .replace(/<style[\s\S]*?<\/style>/gi, "")
      .replace(/<script[\s\S]*?<\/script>/gi, "")
      .replace(
        /<h([1-6])[^>]*>([\s\S]*?)<\/h\1>/gi,
        (_match, level, body) =>
          `${"#".repeat(Number(level))} ${stripHtml(body)}\n\n`,
