export function exportBundles(
  bundles: FolioBundle[],
  format: ExportFormat,
): ExportArtifact {
  if (format === "archive") {
    return {
      format,
      mimeType: "application/json",
      suggestedFilename: "twyne-archive-v2.twyne.json",
      content: `${JSON.stringify(createArchive(bundles), null, 2)}\n`,
    };
